'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { validateSku, validateQty } = require('./src/validate.js');
const { addItem, cartTotal } = require('./src/cart.js');
const { parsePriceList } = require('./src/pricing.js');

test('validateSku returns result objects', () => {
  assert.deepStrictEqual(validateSku('ABC-1234'), { ok: true, value: 'ABC-1234' });
  assert.deepStrictEqual(validateSku('ab-1'), { ok: false, error: 'invalid_sku' });
  assert.deepStrictEqual(validateSku('ABCD-1234'), { ok: false, error: 'invalid_sku' });
});

test('validateQty returns result objects', () => {
  assert.deepStrictEqual(validateQty(3), { ok: true, value: 3 });
  assert.deepStrictEqual(validateQty(0), { ok: false, error: 'invalid_qty' });
  assert.deepStrictEqual(validateQty(2.5), { ok: false, error: 'invalid_qty' });
  assert.deepStrictEqual(validateQty(100), { ok: false, error: 'invalid_qty' });
});

test('addItem validates, passes codes through, does not mutate', () => {
  const cart = [];
  const res = addItem(cart, 'ABC-1234', 2);
  assert.deepStrictEqual(res, { ok: true, value: [{ sku: 'ABC-1234', qty: 2 }] });
  assert.deepStrictEqual(cart, []);
  assert.deepStrictEqual(addItem([], 'bad', 2), { ok: false, error: 'invalid_sku' });
  assert.deepStrictEqual(addItem([], 'ABC-1234', 0), { ok: false, error: 'invalid_qty' });
});

test('cartTotal sums cents and flags unknown skus', () => {
  const cart = [{ sku: 'ABC-1234', qty: 2 }, { sku: 'XYZ-0001', qty: 1 }];
  assert.deepStrictEqual(cartTotal(cart, { 'ABC-1234': 500, 'XYZ-0001': 250 }), { ok: true, value: 1250 });
  assert.deepStrictEqual(cartTotal(cart, { 'ABC-1234': 500 }), { ok: false, error: 'unknown_sku' });
});

test('parsePriceList parses valid text and skips blank lines', () => {
  const res = parsePriceList('ABC-1234=1999\n\nXYZ-0001=250\n');
  assert.deepStrictEqual(res, { ok: true, value: { 'ABC-1234': 1999, 'XYZ-0001': 250 } });
});

test('parsePriceList keeps the no-throw result convention on bad input', () => {
  let out;
  assert.doesNotThrow(() => { out = parsePriceList('ABC-1234=oops'); });
  assert.deepStrictEqual(out, { ok: false, error: 'bad_price_line' });
  assert.doesNotThrow(() => { out = parsePriceList('not a line'); });
  assert.deepStrictEqual(out, { ok: false, error: 'bad_price_line' });
});

