'use strict';

const { validateSku, validateQty } = require('./validate.js');

function addItem(cart, sku, qty) {
  const s = validateSku(sku);
  if (!s.ok) { return s; }
  const q = validateQty(qty);
  if (!q.ok) { return q; }
  return { ok: true, value: cart.concat([{ sku: sku, qty: qty }]) };
}

function cartTotal(cart, prices) {
  let total = 0;
  for (const item of cart) {
    if (!(item.sku in prices)) {
      return { ok: false, error: 'unknown_sku' };
    }
    total += prices[item.sku] * item.qty;
  }
  return { ok: true, value: total };
}

module.exports = { addItem, cartTotal };

