'use strict';

const LINE = /^([A-Z]{3}-[0-9]{4})=([0-9]+)$/;

function parsePriceList(text) {
  if (typeof text !== 'string') {
    return { ok: false, error: 'bad_price_line' };
  }
  const prices = {};
  for (const raw of text.split('\n')) {
    const line = raw.trim();
    if (line === '') { continue; }
    const m = LINE.exec(line);
    if (!m) {
      return { ok: false, error: 'bad_price_line' };
    }
    prices[m[1]] = parseInt(m[2], 10);
  }
  return { ok: true, value: prices };
}

module.exports = { parsePriceList };

