'use strict';

// Result convention for this codebase:
//   { ok: true, value: <result> } | { ok: false, error: '<snake_case_code>' }
function validateName(name) {
  if (typeof name !== 'string' || name.trim().length === 0) {
    return { ok: false, error: 'invalid_name' };
  }
  return { ok: true, value: name.trim() };
}

function validateSku(sku) {
  if (typeof sku !== 'string' || !/^[A-Z]{3}-[0-9]{4}$/.test(sku)) {
    return { ok: false, error: 'invalid_sku' };
  }
  return { ok: true, value: sku };
}

function validateQty(qty) {
  if (!Number.isInteger(qty) || qty < 1 || qty > 99) {
    return { ok: false, error: 'invalid_qty' };
  }
  return { ok: true, value: qty };
}

module.exports = { validateName, validateSku, validateQty };
